import { Router } from "express";
import { authMiddleware } from "../../middleware/auth.js";
import { list, getOne, create, update, remove } from "./controller.js";
const r = Router();
r.use(authMiddleware);
r.get("/", list);
r.get("/:id", getOne);
r.post("/", create);
r.put("/:id", update);
r.delete("/:id", remove);
export default r;
